#!/usr/bin/env bash
# Creates (or promotes) the local admin user through the Supabase Auth admin
# API. The email and password come from deployment/localhost/.env, generated by
# scripts/init-env.sh; nothing is hardcoded.
#
# The services read the admin role from the token's app_metadata.role, not from
# the top-level role claim.
set -euo pipefail

cd "$(dirname "$0")/.."
set -a
# shellcheck disable=SC1091
. ./.env
set +a

base="${SUPABASE_URL:?}"
service_key="${SUPABASE_SERVICE_ROLE_KEY:?}"
email="${ADMIN_EMAIL:-admin@cpb.local}"
password="${ADMIN_PASSWORD:?ADMIN_PASSWORD is missing from .env}"

payload=$(printf '{"email":"%s","password":"%s","email_confirm":true,"app_metadata":{"role":"admin"}}' "$email" "$password")

response=$(curl -sS -w $'\n%{http_code}' -X POST "$base/auth/v1/admin/users" \
  -H "apikey: $service_key" \
  -H "Authorization: Bearer $service_key" \
  -H "Content-Type: application/json" \
  -d "$payload")
code=${response##*$'\n'}
body=${response%$'\n'*}

if [[ "$code" == "200" || "$code" == "201" ]]; then
  echo "Created admin user $email."
  exit 0
fi

if [[ "$code" != "422" ]]; then
  echo "Admin creation failed (HTTP $code): $body" >&2
  exit 1
fi

# The user already exists: find it and make sure the role is set.
user_id=$(
  curl -sS "$base/auth/v1/admin/users?per_page=200" \
    -H "apikey: $service_key" \
    -H "Authorization: Bearer $service_key" |
  EMAIL="$email" node --input-type=module -e '
    let raw = "";
    process.stdin.setEncoding("utf8");
    for await (const chunk of process.stdin) raw += chunk;
    const users = JSON.parse(raw).users ?? [];
    const found = users.find((user) => user.email === process.env.EMAIL);
    if (found) process.stdout.write(found.id);
  '
)

if [[ -z "$user_id" ]]; then
  echo "Admin creation failed: Supabase reported the email exists but it was not listed." >&2
  exit 1
fi

update=$(printf '{"password":"%s","email_confirm":true,"app_metadata":{"role":"admin"}}' "$password")
code=$(curl -sS -o /dev/null -w '%{http_code}' -X PUT "$base/auth/v1/admin/users/$user_id" \
  -H "apikey: $service_key" \
  -H "Authorization: Bearer $service_key" \
  -H "Content-Type: application/json" \
  -d "$update")

if [[ "$code" != "200" ]]; then
  echo "Admin update failed (HTTP $code)." >&2
  exit 1
fi

echo "Admin user $email already existed; role and password refreshed."
